2e876db','crawl',60,NULL),('0a6cd616-6537-4d7c-a988-414d46514d0d',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','pl132005',NULL,'2026-03-20 04:42:13','2026-03-20 04:42:13','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',94,'{\"type\": \"statistical_alias\", \"field\": \"product_reference\", \"value\": \"PL132005\", \"identifier\": \"bloc mémo et post-it grand modèle\", \"product_index\": 84}'),('0a6d4afc-e3d6-4cd7-82b7-0158b71d793e',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','zone',NULL,'2026-02-10 10:03:55','2026-02-10 10:03:55','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',283,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"il vous offre l’équilibre idéal entre douceur et maintien.\\r\\\\n<h2>Pourquoi choisir le Confort Rest ?</h2>\\r\\\\n<ul>\\r\\\\n \\t<li>✨ Un sommeil frais et réparateur</li>\\r\\\\n</ul>\\r\\\\n- Tissu respirant et rafraîchissant qui régule la température et limite la transpiration nocturne.\\r\\\\n- Mousse à mémoire de forme avec gel pour un effet rafraîchissant et un confort enveloppant.\\r\\\\n- Mousse convolutée “egg crate” qui favorise la circulation de l’air et ajoute du moelleux.\\r\\\\n<ul>\\r\\\\n \\t<li>✨ Un soutien adapté à chaque dormeur</li>\\r\\\\n</ul>\\r\\\\n- Ressorts ensachés indépendants qui épousent chaque zone de votre corps.\\r\\\\n- Maintien parfait de la colonne vertébrale et réduction des transferts de mouvement : idéal pour dormir à deux.\\r\\\\n<ul>\\r\\\\n \\t<li>✨ Qualité et praticité au quotidien</li>\\r\\\\n</ul>\\r\\\\n- Livraison roulée en boîte : simple à transporter et à installer\", \"identifier\": \"Matelas Inayya Confort Rest - 90x190\", \"product_index\": 273}'),('0a6f4ad7-f238-497b-84f4-380b4b07b197',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','Product name: Le Pack Lit Rest - Matelas Confort Rest+Lit, 160x200cm. Product type: variation. Price: 928. Discount price: 742,4. Tax rate: taxable. Visibility: visible.',NULL,'2026-02-10 10:06:41','2026-02-10 10:06:41','26f6