INSERT INTO `chunks` VALUES ('0d8c75f7-406d-4cc8-8539-eae209f1a690','774cd267-875d-4bdf-84cc-0bb2f2e73846',NULL,'Page: Blog - Inayya Matelas | Le Site Nº1 de LITERIE à La Réunion ! Section: Comment créer une chambre à coucher idéale pour votre sommeil ? URL: https://inayya.re/blog\n\nLa chambre à coucher est l\'une des pièces les plus importantes de la maison. C\'est l\'endroit où vous passez la majeure partie de votre temps à dormir et à vous reposer. C\'est pourquoi il est important de créer un environnement propice à la détente et au sommeil....',NULL,'2026-02-09 15:12:25','2026-02-09 15:12:25','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','crawl',60,NULL),('0d8e966e-bb1a-4ae0-8371-a145c0805826',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','ajoute',NULL,'2026-02-10 08:58:20','2026-02-10 08:58:20','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',99,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"<strong>cette tête de lit ajoute une touche sophistiquée à n\'importe quelle chambre</strong>. Son design épuré et moderne s\'intègre parfaitement à tous <a href=\\\"https://www.artdeco.re/des-idees-de-decoration-interieure-pour-un-bien-etre-absolu/\\\">les styles de décoration intérieure</a>. Imaginez entrer dans votre chambre et être accueilli par une pièce maîtresse qui respire la classe et le luxe. Ce n\'est pas seulement un ajout esthétique\", \"identifier\": \"Tête de Lit Zenda\", \"product_index\": 89}'),('0d8f2ac9-1cd9-4698-b434-77995c133160',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: 9 cm font li ul ul style margin right 0px',NULL,'2026-03-20 05:42:51','2026-03-20 05:42:51','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',304,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"9 cm</font></li></ul><ul style=\\\"margin-right: 0px\", \"identifier\": \"porte-clés personnalisable en métal et similicuir\", \"product_index\": 294}'),('0d91967f-9845-41ec-9513-cd4e24d9ba49',NULL,'bc12a7c2-c770-4612-b416-7b