", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/50535f6a-9eb1-4625-8c0b-9a1f823b214e.png\", \"identifier\": \"coffret cadeau 3 pièces\", \"product_index\": 121}'),('0dc0708a-dc07-4822-8c4a-c8120a2f9d2b',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','4bbe',NULL,'2026-03-20 06:20:58','2026-03-20 06:20:58','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',430,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/edd04362-3c67-4bbe-a178-346c938af6ac.png\", \"identifier\": \"antistress goutte sang publicitaire\", \"product_index\": 420}'),('0dc0e248-bb62-408c-9417-82055d950c0d',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','123d',NULL,'2026-03-20 12:38:53','2026-03-20 12:38:53','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',84,'{\"type\": \"statistical_alias\", \"field\": \"gallery_urls\", \"value\": \"https://drmaxisliterie.re/assets/resources/products/fef23f86-123d-4e3a-9105-eaa98f7a3225.jpg\", \"identifier\": \"Matelas Elite Confort\", \"product_index\": 74}'),('0dc42768-085c-46dd-a0a6-95024444a8f9',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','moment',NULL,'2026-03-20 12:33:58','2026-03-20 12:33:58','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',59,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"ainsi qu\'à ceux qui souhaitent réduire les perturbations dues aux mouvements de leur partenaire. Un choix parfait pour les amateurs de luxe souhaitant transformer chaque nuit en un moment de détente ultime.\", \"identifier\": \"Matelas Hotel\", \"product_index\": 49}'),('0dc48ae1-fe88-4e72-940f-0e6516656ec0',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: h4 class b font color 000000 lampe porte cles a led noire nbsp',NULL,'2026-03-20 05:03:15','2026-03-20 05:03:15','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',174,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"<h4 class=\\\"\\\"><b><font color=\\\"#000000\\\">Lampe porte-clés à LED noire&nbsp\", \"identifier\": \"porte-clés  lampe torche logo lumineux\", \"product_index\": 164}'),('0dca10cc-20d6-4f8f-9c06-591de5107a4b',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','font strong h4 h4 class strong font color 000000 br font strong ul li font color 000000 matiere s nbsp',NULL,'2026-03-20 04:41:23','2026-03-20 04:41:23','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',90,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"</font></strong></h4><h4 class=\\\"\\\"><strong><font color=\\\"#000000\\\"><br></font></strong><ul><li><font color=\\\"#000000\\\">Matière(s):&nbsp\", \"identifier\": \"porte-clés  publicitaire réctangulaire\", \"product_index\": 80}'),('0dce0ed2-11ba-441f-a2ec-7253b0ba914d',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','Product name: Matelas 37.5 - 160x200. Product type: simple. Product category: Boutique en Ligne, Matelas, Matelas > Matelas 37.5. Description: <span style=\"font-weight: 400;\">Fabriqué en Italie, le <strong>matelas Inayya 37.5</strong> est composé de la</span><b> technologie 37.5,</b><span style=\"font-weight: 400;\"> vous apportera un <strong>sommeil réparateur</strong>. Elle a obtenu la certification en tant que Dispositif Médical enregistré auprès du </span><b>Ministère de la Santé italien</b><span style=\"font-weight: 400;\">.</span>\r\\n<h5><span style=\"color: #00a6cf;\"><strong>L’INNOVATION DE LA TECHNOLOGIE 37.5</strong></span></h5>\r\\n<b>Cette technologie brevetée est unique et utilisée par d’importantes marques</b><span style=\"font-weight: 400;\"> du sport telles qu’</span><b>Adidas</b><span style=\"font-weight: 400;\">, </span><b>Asics, Puma, Rip Curl</b><span style=\"font-weight: 400;\"> ou </span><b>Under Armour</b><span style=\"font-weight: 400;\">. Le tissu 37.5 est certifié hypoallergénique, testé par des </span><b>laboratoires européens</b><span style=\"font-weight: 400;\"> indépendants et par le </span><b>US Olympic Training Center</b><span style=\"font-weight: 400;\">.</span> <span style=\"font-weight: 400;\">La vapeur invisible que le corps libère pendant le sommeil peut créer de l’humidité dans le lit, ce qui accommodera le dormeur. </span><b>Le tissu 37.5 l’élimine </b><span style=\"font-weight: 400;\">avant même qu’elle soit perçue et transformée en sueur.</span> <span style=\"font-weight: 400;\">Avec le <strong>matelas Inayya 37.5</strong>, fini la sensation de froid en hiver et de chaleur en été  causée par l’humidité produite par votre corps et mal évacuée par votre matelas. Ce dernier vous procurera <strong>un sommeil apaisant.</strong></span>\r\\n<h5><span style=\"color: #00a6cf;\"><strong>COMMENT FONCTIONNE LE  37.5 ?</strong></span></h5>\r\\n<b>Les particules actives d’origine naturelle</b><span style=\"font-weight: 400;\"> (minéraux volcaniques et coquilles de noix de coco) attirent et éliminent l’excès de vapeur d’eau ainsi que les odeurs désagréables, le micro-climat interne du lit reste constant. L’énorme point fort de la technologie 37.5, c’est qu’elle interagit avec les rayons infrarouges de la personne, </span><b>s’adaptant aux besoins de chacun</b><span style=\"font-weight: 400;\">. Facteur très important quand 2 personnes ayant des caractéristiques physiques différentes dorment dans le lit.</span>\r\\n<h5><span style=\"color: #00a6cf;\"><strong>LA MOUSSE GEL MEMORY BREEZE</strong></span></h5>\r\\n<span style=\"font-weight: 400;\">La forme à cellules ouvertes de <strong>la mousse gel à mémoire de forme</strong> garantit la circulation de l’air et </span><b>la dispersion rapide de l’humidité et de la chaleur</b><span style=\"font-weight: 400;\">. Les caractéristiques de </span><b>résistance au vieillissement et à la déformation</b><span style=\"font-weight: 400;\"> permettent à la mousse de donner une sensation de bien-être maximale, assurant ainsi un repos complet.</span>\r\\n<h5><span style=\"color: #00a6cf;\"><strong>LA MOUSSE PUR-O</strong></span></h5>\r\\n<span style=\"font-weight: 400;\">Mousse évoluée sans CFC qui offre un excellent rendement élastique et ergonomie. PUR-O assure un confort optimal et une </span><b>position parfaite de la colonne vertébrale. Une</b> <strong>véritable expérience de sommeil sans inquiétude</strong>\r\\n<h4><span style=\"color: #00a6cf;\"><strong>LA MOUSSE POLYURÉTHANE</strong></span></h4>\r\\n<span style=\"font-weight: 400;\">Le polyuréthane se caractérise par sa </span><b>faible résistance à la compression et à l’affaissement</b><span style=\"font-weight: 400;\">. Également, la perméabilité à l’air qui montre une plus grande respirabilité du matelas. La densité de 30kg/m2 offre un meilleur soutien du poids, garantissant un sommeil régénérateur.</span>. Price: 1149. Discount price: 861,75. Tax rate: taxable. Short description: La technologie 37.5 au service de votre sommeil : respirabilité, gestion de l\'humidité, confort et régulation du microclimat.. Visibility: visible.',NULL,'2026-02-10 09:21:12','2026-02-10 09:21:12','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',147,'{\"raw\": {\"tags\": \"\", \"brand\": \"\", \"price\": \"1149\", \"weight\": \"\", \"tax_rate\": \"taxable\", \"dimensions\": \"\", \"visibility\": \"visible\", \"description\": \"<span style=\\\"font-weight: 400;\\\">Fabriqué en Italie, le <strong>matelas Inayya 37.5</strong> est composé de la</span><b> technologie 37.5,</b><span style=\\\"font-weight: 400;\\\"> vous apportera un <strong>sommeil réparateur</strong>. Elle a obtenu la certification en tant que Dispositif Médical enregistré auprès du </span><b>Ministère de la Santé italien</b><span style=\\\"font-weight: 400;\\\">.</span>\\r\\\\n<h5><span style=\\\"color: #00a6cf;\\\"><strong>L’INNOVATION DE LA TECHNOLOGIE 37.5</strong></span></h5>\\r\\\\n<b>Cette technologie brevetée est unique et utilisée par d’importantes marques</b><span style=\\\"font-weight: 400;\\\"> du sport telles qu’</span><b>Adidas</b><span style=\\\"font-weight: 400;\\\">, </span><b>Asics, Puma, Rip Curl</b><span style=\\\"font-weight: 400;\\\"> ou </span><b>Under Armour</b><span style=\\\"font-weight: 400;\\\">. Le tissu 37.5 est certifié hypoallergénique, testé par des </span><b>laboratoires européens</b><span style=\\\"font-weight: 400;\\\"> indépendants et par le </span><b>US Olympic Training Center</b><span style=\\\"font-weight: 400;\\\">.</span> <span style=\\\"font-weight: 400;\\\">La vapeur invisible que le corps libère pendant le sommeil peut créer de l’humidité dans le lit, ce qui accommodera le dormeur. </span><b>Le tissu 37.5 l’élimine </b><span style=\\\"font-weight: 400;\\\">avant même qu’elle soit perçue et transformée en sueur.</span> <span style=\\\"font-weight: 400;\\\">Avec le <strong>matelas Inayya 37.5</strong>, fini la sensation de froid en hiver et de chaleur en été  causée par l’humidité produite par votre corps et mal évacuée par votre matelas. Ce dernier vous procurera <strong>un sommeil apaisant.</strong></span>\\r\\\\n<h5><span style=\\\"color: #00a6cf;\\\"><strong>COMMENT FONCTIONNE LE  37.5 ?</strong></span></h5>\\r\\\\n<b>Les particules actives d’origine naturelle</b><span style=\\\"font-weight: 400;\\\"> (minéraux volcaniques et coquilles de noix de coco) attirent et éliminent l’excès de vapeur d’eau ainsi que les odeurs désagréables, le micro-climat interne du lit reste constant. L’énorme point fort de la technologie 37.5, c’est qu’elle interagit avec les rayons infrarouges de la personne, </span><b>s’adaptant aux besoins de chacun</b><span style=\\\"font-weight: 400;\\\">. Facteur très important quand 2 personnes ayant des caractéristiques physiques différentes dorment dans le lit.</span>\\r\\\\n<h5><span style=\\\"color: #00a6cf;\\\"><strong>LA MOUSSE GEL MEMORY BREEZE</strong></span></h5>\\r\\\\n<span style=\\\"font-weight: 400;\\\">La forme à cellules ouvertes de <strong>la mousse gel à mémoire de forme</strong> garantit la circulation de l’air et </span><b>la dispersion rapide de l’humidité et de la chaleur</b><span style=\\\"font-weight: 400;\\\">. Les caractéristiques de </span><b>résistance au vieillissement et à la déformation</b><span style=\\\"font-weight: 400;\\\"> permettent à la mousse de donner une sensation de bien-être maximale, assurant ainsi un repos complet.</span>\\r\\\\n<h5><span style=\\\"color: #00a6cf;\\\"><strong>LA MOUSSE PUR-O</strong></span></h5>\\r\\\\n<span style=\\\"font-weight: 400;\\\">Mousse évoluée sans CFC qui offre un excellent rendement élastique et ergonomie. PUR-O assure un confort optimal et une </span><b>position parfaite de la colonne vertébrale. Une</b> <strong>véritable expérience de sommeil sans inquiétude</strong>\\r\\\\n<h4><span style=\\\"color: #00a6cf;\\\"><strong>LA MOUSSE POLYURÉTHANE</strong></span></h4>\\r\\\\n<span style=\\\"font-weight: 400;\\\">Le polyuréthane se caractérise par sa </span><b>faible résistance à la compression et à l’affaissement</b><span style=\\\"font-weight: 400;\\\">. Également, la perméabilité à l’air qui montre une plus grande respirabilité du matelas. La densité de 30kg/m2 offre un meilleur soutien du poids, garantissant un sommeil régénérateur.</span>\", \"product_url\": \"\", \"availability\": \"0\", \"product_name\": \"Matelas 37.5 - 160x200\", \"product_type\": \"simple\", \"stock_status\": \"\", \"discount_price\": \"861,75\", \"product_category\": \"Boutique en Ligne, Matelas, Matelas > Matelas 37.5\", \"product_reference\": \"\", \"short_description\": \"La technologie 37.5 au service de votre sommeil : respirabilité, gestion de l\'humidité, confort et régulation du microclimat.\"}, \"type\": \"global\", \"identifier\": \"Matelas 37.5 - 160x200\", \"product_index\": 147}'),('0dd45ed6-8f64-4474-b512-10519ce8993d',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','created at: 2025 04 09 16 25 05',NULL,'2026-03-20 05:03:59','2026-03-20 05:03:59','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',175,'{\"type\": \"statistical_alias\", \"field\": \"created_at\", \"value\": \"2025-04-09 16:2