6-cbdfcf1060d6',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','ab95',NULL,'2026-03-20 12:33:12','2026-03-20 12:33:12','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',53,'{\"type\": \"statistical_alias\", \"field\": \"gallery_urls\", \"value\": \"https://drmaxisliterie.re/assets/resources/products/66498df1-0e66-4201-ab95-5724709a002f.jpg\", \"identifier\": \"Matelas Ambassadeur\", \"product_index\": 43}'),('20f95b78-e96a-47a1-8d35-b0dcee2df1d6','5716bdc9-4e63-491b-9a10-8983d0fbc017',NULL,'ntre eux.</p>\r\n<p style=\"font-weight: 350;\">Les ressorts Bonnell sont reliés entre eux pour former une structure solide. Ces matelas offrent une bonne aération, mais peuvent être moins confortables pour les personnes ayant des douleurs dorsales, car ils ne s\'adaptent pas aussi bien à la forme du corps.</p>\r\n<p style=\"font-weight: 350;\">Les ressorts ensachés sont chacun enveloppé individuellement dans un sachet de tissu. Ce type de matelas offre un meilleur soutien, car les ressorts réagissent indépendamment aux mouvements du corps, réduisant ainsi les points de pression et offrant une meilleure indépendance de couchage.</p>\r\n<p style=\"font-weight: 350;\">Certes, le matelas en mousse est un choix idéal parmi les consommateurs.',NULL,'2026-02-16 18:22:44','2026-02-16 18:22:44','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('20fbce16-5194-4f78-944a-3c32c5b3998a',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','5 cm font li li font color 000000 dimension verre taille m 17',NULL,'2026-03-20 06:29:05','2026-03-20 06:29:05','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',457,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"5 cm</font></li><li><font color=\\\"#000000\\\">Dimension verre (Taille M): 17\", \"identifier\": \"trophées en verre forme circulaire\", \"product_index\": 447}'),('20fe62dd-2636-4933-8694-38555f228d8c',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','1155',NULL,'2026-03-20 06:37:26','2026-03-20 06:37:26','1e0d17be-c7ef-