nteragir librement pendant que vous cuisinez.',NULL,'2026-02-16 16:19:20','2026-02-16 16:19:20','d75f16dd-64a5-47eb-a13b-290285cd85af','import',50,NULL),('25fd9ebb-fd0d-4800-aee3-ee4e94e3bca9',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','li li dimension note book 23',NULL,'2026-03-20 05:01:22','2026-03-20 05:01:22','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',165,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"</li><li>Dimension Note book: 23\", \"identifier\": \"notebook a5 en similicuir de type classeur \", \"product_index\": 155}'),('26088cb1-ca88-4e76-a03a-8d727931def9',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','au design epure',NULL,'2026-03-20 12:40:07','2026-03-20 12:40:07','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',100,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"au design épuré\", \"identifier\": \"Lit Prestige\", \"product_index\": 90}'),('260e2b5b-e01d-465b-9c8a-1cbd0e6094fa',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','https planetdesign ma assets resources articles 9117484c ba1c 4736 ba45 b46b616e6625 png',NULL,'2026-03-20 05:10:14','2026-03-20 05:10:14','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',196,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/9117484c-ba1c-4736-ba45-b46b616e6625.png\", \"identifier\": \"stylo en métal  promotionnel avec boite\", \"product_index\": 186}'),('260f7bb6-b78e-4aaf-bf9c-f4420042f8c3',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','product url: https planetdesign ma article porte cles lampe torche logo lumineux pl141133 nr',NULL,'2026-03-20 05:03:26','2026-03-20 05:03:26','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',174,'{\"type\": \"statistical_alias\", \"field\": \"product_url\", \"value\": \"https://planetdesign.ma/article/porte-cles-lampe-torche-logo-lumineux/PL141133-NR\", \"identifier\": \"porte-clés  lampe torche logo lumineux\", \"product_index\": 