'3b584e72-fa10-4c1e-94f7-e667df9d3eaf','d7cbc997-7cb2-4e4b-809d-6c5af4807376',NULL,'de cuisine en granit sont lourds ; ils ont besoin d\'un support solide pour s\'asseoir magnifiquement dans votre cuisine. Ils ne peuvent pas être simplement accrochés à votre comptoir.</span></p>\n<ul>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">N\'optez pas pour les fonds plats : Les éviers en granit à fond plat ont moins d\'efficacité de drainage. Il y a des chances que de l\'eau résiduelle reste au fond de l\'évier et ne sorte pas par le bac égouttoir.</span></li>\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Assorti à votre plan de travail : Pour que votre cuisine soit esthétiquement attrayante, vous devez compléter le plan de travail avec l\'évier de cuisine.',NULL,'2026-02-16 16:24:38','2026-02-16 16:24:38','d75f16dd-64a5-47eb-a13b-290285cd85af','import',50,NULL),('3b5a64ea-dd78-4314-b248-a4974ffcc511',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: font color 000000 format a5 font li li style border none',NULL,'2026-03-20 05:20:32','2026-03-20 05:20:32','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',231,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\"><font color=\\\"#000000\\\">Format: A5</font></li><li style=\\\"border: none\", \"identifier\": \"set notebook a5 en liège et similicuir avec stylo\", \"product_index\": 221}'),('3b5ce683-c445-46db-b6be-feaec04d29e3',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','br n url https www inayya com produit matelas inayya',NULL,'2026-02-10 08:54:45','2026-02-10 08:54:45','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',83,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"<br />\\r\\\\n  \\\"url\\\" : \\\"https://www.inayya.com/produit/matelas-inayya/\\\"\", \"identifier\": \"Couette Premium Gamme Hôtel\", \"product_index\": 73}'),('3b6276af-92f9-465c-8d76-bfd8ae4d9375',NULL,'bc12a7c2-c