us risquez d’être déçu par un <strong>matelas</strong> trop fermé. Pour les morphologies plus hachées, un matelas plus doux est le meilleur choix.',NULL,'2026-02-16 18:37:13','2026-02-16 18:37:13','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('3cb7c432-83fb-4d85-91df-91ad78429555',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: 4x35',NULL,'2026-03-20 04:33:14','2026-03-20 04:33:14','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',61,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"4x35\", \"identifier\": \"housse de protection pour ordinateur portable 15\\\"\", \"product_index\": 51}'),('3cbb680f-e1c6-48ce-bd0c-e77d5ef4f072',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','modele',NULL,'2026-03-20 04:42:13','2026-03-20 04:42:13','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',94,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"bloc mémo et post-it grand modèle\", \"identifier\": \"bloc mémo et post-it grand modèle\", \"product_index\": 84}'),('3cc43948-ae92-476d-9a32-73c74716b5c1',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: pieces par carton 40 pcs font li ul ul style color rgb 94',NULL,'2026-03-20 06:37:07','2026-03-20 06:37:07','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',479,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\">Pièces par carton: 40 pcs</font></li></ul><ul style=\\\"color: rgb(94\", \"identifier\": \"power-bank 10000 mah avec miroir intégré\", \"product_index\": 469}'),('3cc49519-191c-4666-a49c-e9aea905a2b4',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','2025 02 03 22 06 40',NULL,'2026-03-20 04:24:05','2026-03-20 04:24:05','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',34,'{\"type\": \"statistical_alias\", \"field\": \"created_at\", \"value\": \"2025-02-03 22:06:40\", \"identifier\": \"calculatrice de bureau 12 digit\", \"product_index\": 24}'),('3cc51d86-5f7f-45d3-95c6-5a14c30d935b',NULL,'bc12a7c2-c770-4612-b416-