. Prenez le temps d\'explorer ces astuces et de perfectionner vos compétences culinaires pour impressionner votre famille et vos amis avec des plats délicieux et dignes d\'un chef. Bon appétit !',NULL,'2026-02-16 16:17:16','2026-02-16 16:17:16','d75f16dd-64a5-47eb-a13b-290285cd85af','import',50,NULL),('4642dc3d-640e-4ce3-a1b7-cdb5dc3d6cfa',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: serigraphie li ul',NULL,'2026-03-20 04:45:34','2026-03-20 04:45:34','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',105,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"Sérigraphie</li></ul>\", \"identifier\": \"cube papier ecologique avec post-it\", \"product_index\": 95}'),('464a2494-1cf8-4dc3-b699-f2f1082e85a4',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','78x39',NULL,'2026-03-20 04:15:07','2026-03-20 04:15:07','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',14,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"78x39\", \"identifier\": \"thermos bouteille isotherme en inox et bois 500 ml\", \"product_index\": 4}'),('464a3791-de1f-48b5-a537-c54748b627f5',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','4edf',NULL,'2026-03-20 05:28:18','2026-03-20 05:28:18','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',256,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/e8a92fdf-5bac-4edf-8325-a11690bf7e78.png\", \"identifier\": \"cartable pour ordinateur portable et documents\", \"product_index\": 246}'),('464a6bd1-6d5f-4cb3-bca2-1d755ac149f3',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','pl425009',NULL,'2026-03-20 04:49:02','2026-03-20 04:49:02','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',120,'{\"type\": \"statistical_alias\", \"field\": \"product_reference\", \"value\": \"PL425009\", \"identifier\": \"sac non-tissé publicitaire\", \"product_index\": 110}'),('464f2d9f-2f61-40a5-a52f-fe8b8d853aff',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','s