INSERT INTO `chunks` VALUES ('484c8d28-d9c2-4377-9bee-8454cabbd77d','91e55f51-dfb5-4687-81c0-89fa3a73b13c',NULL,'le charme vintage, ou le glamour moderne,</strong> vous trouverez une tête de lit qui complémente votre style personnel. <strong>Faites de votre lit le point focal</strong> de la chambre en choisissant une pièce qui résonne avec votre personnalité. <strong>-Charme Vintage :</strong> Pour ceux qui apprécient l\'histoire et le caractère, <strong>une tête de lit au style vintage </strong>peut être la clé. <strong>Des détails classiques, des finitions patinées </strong>et des motifs rétro apporteront une touche d\'élégance nostalgique à votre chambre. <strong>-Glamour Moderne :</strong> Les amateurs de luxe contemporain seront séduits<strong> par nos têtes de lit</strong> au design sophistiqué.',NULL,'2026-02-16 18:27:41','2026-02-16 18:27:41','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('484cd004-2484-423f-9751-95355c22ed46',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','la conception avanc ee de strong notre matelas confort plus strong garantit un soutien optimal a chaque strong point du corps strong',NULL,'2026-02-10 09:28:51','2026-02-10 09:28:51','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',170,'{\"type\": \"statistical_alias\", \"field\": \"short_description\", \"value\": \"La conception avancée de <strong>notre matelas Confort Plus</strong> garantit un soutien optimal à chaque <strong>point du corps</strong>\", \"identifier\": \"Matelas Inayya Confort Plus - 90x190\", \"product_index\": 160}'),('484d7242-b6df-4fb2-a4ff-de8f7c902fca',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','precis',NULL,'2026-03-20 12:36:07','2026-03-20 12:36:07','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',72,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"Le Matelas ROYAL 4 Étoiles offre un confort optimal grâce à sa mousse à mémoire de forme avec gel et ses micro-ressorts ensachés. Sa fibre Eco Confort régule la température pour une sensation de fraîcheur. L\'encadrement en mousse et les couches épaisses soulignent son soutien précis. Le tissu en coton traité et la mousse Dacron apportent douceur et confort. Un matelas conçu pour un sommeil réparateur de qualité supérieure.    GARANTIE 10 ANS. Le Matelas ROYAL 4 Étoiles est conçu pour les personnes à la recherche d’un confort haut de gamme avec un soutien personnalisé et une qualité de sommeil optimale. Il est idéal pour les couples\", \"identifier\": \"Matelas Royal 4 Etoiles\", \"product_index\": 62}'),('484dbccc-b3ec-4f8c-a206-e41bb19c4339',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','2025 02 01 10 18 54',NULL,'2026-03-20 05:24:53','2026-03-20 05:24:53','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',244,'{\"type\": \"statistical_alias\", \"field\": \"created_at\", \"value\": \"2025-02-01 10:18:54\", \"identifier\": \"note book a5 en similicuir forme pochette \", \"product_index\": 234}'),('48506376-817c-4e26-9cdf-ed3f9168d69c',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','accueil',NULL,'2026-03-20 12:33:23','2026-03-20 12:33:23','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',56,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"évitant l’accumulation de chaleur. Les renforts autour des bords offrent une stabilité et une durabilité accrues.    GARANTIE 10 ANS. Le Matelas PALACE est destiné aux personnes recherchant le summum du confort et du luxe dans leur literie. Il convient particulièrement à ceux qui privilégient un accueil doux et un soutien optimal grâce à ses matériaux haut de gamme tels que le duvet d\'oie et la soie naturelle. Ce matelas est idéal pour les couples\", \"identifier\": \"Matelas Palace\", \"product_index\": 46}'),('4856186f-6faa-406b-aa1e-a86f8375e887',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','b475a328',NULL,'2026-03-20 06:01:38','2026-03-20 06:01:38','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',366,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"valu