 touche d’élégance et de modernité à votre espace.',NULL,'2026-02-09 15:40:18','2026-02-09 15:40:18','d75f16dd-64a5-47eb-a13b-290285cd85af','sitemap',80,NULL),('5746fe59-a7cd-48f0-97e6-ffbdcaeeefee',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','serein',NULL,'2026-03-20 12:40:50','2026-03-20 12:40:50','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',109,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"le Lit Confort crée un environnement serein et agréable\", \"identifier\": \"Lit Confort\", \"product_index\": 99}'),('57477544-87c7-4b9d-86eb-ea871f0228eb',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','brand',NULL,'2026-02-10 08:54:48','2026-02-10 08:54:48','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',83,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"<br />\\r\\\\n  \\\"brand\\\" : {<br />\\r\\\\n    \\\"@type\\\" : \\\"Brand\\\"\", \"identifier\": \"Couette Premium Gamme Hôtel\", \"product_index\": 73}'),('57480ae7-65a9-4919-a145-efdd8b0cd170',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','product name: sommier tissu 3d 90x190cm',NULL,'2026-02-10 08:43:33','2026-02-10 08:43:33','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',20,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"Sommier Tissu 3D - 90x190cm\", \"identifier\": \"Sommier Tissu 3D - 90x190cm\", \"product_index\": 10}'),('574b5b6c-a19b-4051-85ec-0752f46a9baa',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: matiere s verre',NULL,'2026-03-20 04:33:54','2026-03-20 04:33:54','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',63,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\">Matière(s): Verre\", \"identifier\": \"bouteille en verre  à bouchon en bamboo  avec pochette 600 ml\", \"product_index\": 53}'),('574bc67f-b232-4a56-977f-0a5a38a03aeb',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','rand',NULL,'2026-02-10 08:56:07','2026-02-10 08:56:07','26f613e9-bd9c-4ee3-b194-5a84b6c1a4