INSERT INTO `chunks` VALUES ('57b8f2c8-1648-4f55-a6af-8b9a82b6fb1a','10f9ac42-18bd-4b73-af91-b6a6e5b14899',NULL,'s. <strong>Les matelas adaptés à votre confort</strong> sont conçus pour réduire les points de pression sur votre corps. Ils doivent répartir votre poids pour soulager les douleurs et les tensions.<strong> </strong>\r\n<ol start=\"5\">\r\n 	<li style=\"list-style-type: none;\">\r\n<ol start=\"5\">\r\n 	<li><strong> Matelas Ajustables</strong></li>\r\n</ol>\r\n</li>\r\n</ol>\r\n<img class=\"alignnone size-medium wp-image-31330\" src=\"https://inayya.re/wp-content/uploads/2023/10/matelas-adapte3.jpg\" alt=\"Un matelas adapté à votre confort\" />\r\n\r\nChaque personne à <strong>des préférences différentes en matière de fermeté du matelas.</strong> Un matelas adapté <strong>à votre confort</strong> vous permet de régler <strong>le niveau de fermeté selon vos besoins</strong>.',NULL,'2026-02-16 18:31:19','2026-02-16 18:31:19','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('57ba34e7-a66d-4597-9da8-5b9924b15825',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','20ff2e4259cc',NULL,'2026-03-20 04:37:01','2026-03-20 04:37:01','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',72,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/d51f8e0d-e664-4c04-ad0f-20ff2e4259cc.png\", \"identifier\": \"coffret note-book avec ouverture forme boucle\", \"product_index\": 62}'),('57bbe00b-cdd7-44dc-98c9-8bdcf8fa1cc8','2d47df2e-4a25-4bef-a725-3f739a35bb73',NULL,'résistant à la chaleur</strong>\r\n\r\nLes plats chauds ne laissent aucune trace sur les plans en céramique cuisine habitat. <strong>Résistant aux chocs</strong>\r\n\r\nLa grande stabilité du matériau vous permet d\'être facilement un peu plus lourd parfois lorsque vous posez des casseroles ou des poêles. <strong>Résistant aux rayures et aux coupures</strong>\r\n\r\nLa surface de haute qualité est si robuste que même les couteaux ne laissent pratiquement aucune trace. <strong>Hygiénique et sans danger pour les aliments</strong>\r\n\r\nLe matériau naturel est neutre en odeur et en goût et donc absolument sans danger pour les aliments. <strong>Incroyable résistance aux taches</strong>\r\n\r\nLes aliments et les boissons ne laissent aucune trace permanente sur la surface de nos éviers en céramique.',NULL,'2026-02-16 16:22:56','2026-02-16 16:22:56','d75f16dd-64a5-47eb-a13b-290285cd85af','import',50,NULL),('57bd0975-e770-4fab-a6ef-0d2a4984ad79',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','le pack inayya slumber',NULL,'2026-02-10 10:13:49','2026-02-10 10:13:49','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',355,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"Le Pack Inayya Slumber\", \"identifier\": \"Le Pack Inayya Slumber\", \"product_index\": 345}'),('57bfdd5b-7148-41cc-aad9-ebb6bdd05ed2',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','description: chaque strong sommier tapissier gris design strong est soigneusement fabriqu e avec des mat eriaux de qualit e sup erieure et un souci du d etail son assemblage pr ecis garantit une stabilit e maximale',NULL,'2026-02-10 09:42:24','2026-02-10 09:42:24','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',209,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\">Chaque <strong>sommier tapissier gris design</strong> est soigneusement fabriqué avec des matériaux de qualité supérieure et un souci du détail. Son assemblage précis garantit une stabilité maximale\", \"identifier\": \"SOMMIER TAPISSIER GRIS\", \"product_index\": 199}'),('57c1962a-1ee2-44ed-a40a-b31ce280063b',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','strong un oreiller pour chaque style de sommeil strong h2 n h3 style color 000000',NULL,'2026-02-10 08:39:02','2026-02-10 08:39:02','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',12,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\"><strong>Un Oreiller pour Chaque