aires chaque jour pour réguler votre horloge interne. Le choix du matelas peut avoir un impact significatif sur la qualité de votre sommeil et sur votre niveau d\'énergie au réveil.',NULL,'2026-02-16 18:32:02','2026-02-16 18:32:02','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('6c213a16-dbe9-452a-b732-2d7ac974dc59',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','casques',NULL,'2026-03-20 04:18:31','2026-03-20 04:18:31','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',20,'{\"type\": \"statistical_alias\", \"field\": \"tags\", \"value\": \"haut parleurs & casques\", \"identifier\": \"haut parleur et earbuds\", \"product_index\": 10}'),('6c22d78d-c181-4b30-a4ef-dd25cdcf125c',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','description: strong matelas a m emoire de forme strong fabriqu e en italie',NULL,'2026-02-10 09:13:43','2026-02-10 09:13:43','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',149,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\"><strong>Matelas à mémoire de forme</strong> fabriqué en Italie\", \"identifier\": \"Matelas Inayya First - 90x190\", \"product_index\": 139}'),('6c25770c-085d-4e33-bea5-7e7b083a2572',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','Product name: parure de stylos dorés avec boite. Product reference: PL117012-DO. Product type: variation. Product category: écriture. Tags: PARURES DE STYLOS. Colors: doré. Materials: métal. Availability: en stock. Image url: https://planetdesign.ma/assets/resources/articles/98579ec1-d6d3-414c-8197-56bf4a8f4a0e.png. Product url: https://planetdesign.ma/article/parure-de-stylos-dores-avec-boite/PL117012-DO. Created at: 2025-01-28 20:57:34.',NULL,'2026-03-20 05:22:55','2026-03-20 05:22:55','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',226,'{\"raw\": {\"tags\": \"PARURES DE STYLOS\", \"brand\": \"\", \"price\": \"\", \"colors\": \"doré\", \"status\": \"\", \"weight\": \"\", \"currency\": \"\", \"features\": \"\", \"keywords\": \"\", \"language\": \"\", \"t