c4bed4df','6x28x3',NULL,'2026-03-20 05:51:26','2026-03-20 05:51:26','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',333,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"6x28x3\", \"identifier\": \"coffret  bloc note et porte cles usb 32gb et stylo\", \"product_index\": 323}'),('892f18e8-e98b-4a46-beae-e6acd67bca78','48a31a0d-f785-47ad-8963-067bd30882f1',NULL,'nnalités qui pourraient améliorer votre sommeil, il peut être intéressant d\'en visager le remplacement de votre matelas. Par exemple, les matelas en mousse à mémoire de forme, les matelas hybrides ou les matelas réglables sont quelques-unes des options populaires offrant un soutien et un confort supérieurs. <h2>Taches, odeurs et moisissures :</h2>\r\nSi votre matelas présente des taches tenaces, des odeurs persistantes ou montre des signes de moisissure, il est temps de dire au revoir à votre vieux matelas. Ces problèmes peuvent affecter la qualité de l\'air dans votre chambre à coucher et peuvent également être nuisibles pour votre santé. Un matelas propre et sans odeur est essentiel pour un environnement de sommeil sain.',NULL,'2026-02-16 18:32:19','2026-02-16 18:32:19','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('892f81c8-3709-45a3-b8bf-95fc97c9eef0',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','42e1',NULL,'2026-03-20 05:54:50','2026-03-20 05:54:50','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',344,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/4db8b374-3a7b-42e1-98fc-a34c3131802b.png\", \"identifier\": \"usb publicitaire rotative 32 gb\", \"product_index\": 334}'),('89321453-5a06-440f-a22d-eea7c716ea6e',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','t etes de lit',NULL,'2026-02-10 08:55:58','2026-02-10 08:55:58','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',85,'{\"type\": \"statistical_alias\", \"field\": \"product_category\", \"value\": \"Têtes de Lit\", \"identifier\": \"T