,('945876dc-d815-4568-b7a4-0d8a60a606b4',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','ce matelas est le choix parfait pour des nuits reposantes p n n h2 style color 000000',NULL,'2026-02-10 09:47:21','2026-02-10 09:47:21','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',222,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"ce matelas est le choix parfait pour des nuits reposantes.</p>\\r\\\\n\\r\\\\n<h2 style=\\\"color: #000000\", \"identifier\": \"Le Pack Lit Confort\", \"product_index\": 212}'),('945a135a-b6ab-4bff-9991-b890c871df4a',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','1548',NULL,'2026-02-10 08:52:40','2026-02-10 08:52:40','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',78,'{\"type\": \"statistical_alias\", \"field\": \"price\", \"value\": \"1548\", \"identifier\": \"Le Pack Inayya - Matelas First+Sommier, 160x200cm\", \"product_index\": 68}'),('945dd1ca-0328-46b0-93d6-531dc6ee898a','8e6ec86f-90bc-4578-8792-a586ca213c01',NULL,'Page: Luttez contre l’insomnie grâce aux huiles essentiels !!!! URL: https://inayya.re/luttez-contre-linsomnie-grace-aux-huiles-essentiels\n\nLes<strong> huiles essentielles</strong> deviennent de plus en plus indispensables dans notre vie. Elles servent à traiter plusieurs indispositions de la vie de tous les jours. Elles opèrent principalement sur le système immunitaire de l’organisme et lutter contre des infections virales et bactériennes mais aussi agir contre <strong>l’insomnie</strong>. Qui n’a jamais connu l’insomnie ? En médecine <strong>l’insomnie </strong>rentre dans la famille des troubles de sommeil, et se caractérise par une <strong>difficulté à dormir</strong> suffisamment. 40% des français en souffrent et 20% d’eux suivent un traitement pour s’en débarrasser.',NULL,'2026-02-16 18:35:57','2026-02-16 18:35:57','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('9461b8d5-0243-4f49-a794-0b3f88beffbf','ae8ba93c-cd6f-4803-ac5e-d290f0a3b4f8',NULL,'://www.inayya.com/produit/oreillers-inayya/\">oreiller</a>...) est elle aussi importante pour améliorer l\'endormissement. <div dir=\"auto\">\r\n<h3>Récupèrer avec une grasse matinée</h3>\r\n</div>\r\n<div dir=\"auto\">Peut-on faire la grasse matinée le week-end pour compenser le manque de sommeil de la semaine?</div>\r\n<div dir=\"auto\">Qui ne rêve pas d\'une bonne grasse matinée, allongez sur un bon<strong> matelas</strong>, la tête posée sur son <strong>oreiller</strong>, bien installé sous la couette ?</div>\r\n<div dir=\"auto\">Mais attention la grasse matinée, vous permettra seulement de récupérer une partie de votre sommeil.</div>\r\n<div dir=\"auto\">Néanmoins, il est préférable d\'éviter de trop retarder votre réveil, quitte à y ajouter une sieste de courte durée en début d\'après-midi.</div>\r\n<div dir=\"auto\">Si vous retardez votre réveil de plus de  deux heures, votre sommeil sera beaucoup moins récupérateur.',NULL,'2026-02-16 18:42:23','2026-02-16 18:42:23','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('946ae28f-53e4-4791-8564-244908ad9a25',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','description: du sport telles qu span b adidas b span style font weight 400',NULL,'2026-02-10 08:51:53','2026-02-10 08:51:53','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',77,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\"> du sport telles qu’</span><b>Adidas</b><span style=\\\"font-weight: 400\", \"identifier\": \"Le Pack Inayya\", \"product_index\": 67}'),('946f162a-8343-4f48-bb15-8e82f2eee680',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','matiere s tissu polypropylene font li li font color 000000 grammage 80 g m2 font li li font color 000000 dimensions 38x30x10 cm font li li style margin 0px',NULL,'2026-03-20 05:09:06','2026-03-20 05:09:06','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',193,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\">Matière(s): Tissu (Polypropylène)</font></li><li><font color=\\\"#000000\\\">Grammage: 80 g/m²</font></li><li><font color=\\\"#000000\\\">Dimensions: 38x30x10 cm</font></li><li style=\\\"margin: 0px\", \"identifier\": \"sac non-tissé imprimable\", \"product_index\": 183}'),('9472cfd2-b0e9-4de1-a443-9e4e03a7ff0d','6a94ab82-8715-4fc5-af76-e0cf86310d70',NULL,'</strong></h2>\r\nDe nombreuses études scientifiques ont démontré l’impact direct du sommeil sur les fonctions cognitives. Lorsque vous dormez, votre cerveau ne se « déconnecte » pas, au contraire : il trie, consolide et organise les informations apprises durant la journée. Il se débarrasse également des toxines accumulées, recharge les circuits neuronaux, et prépare le terrain pour un nouveau jour d’apprentissage.',NULL,'2026-02-16 18:19:29','2026-02-16 18:19:29','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('947bd449-7d93-4802-b7bc-5ec2b0d94c2d',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','thirtysevenfive',NULL,'2026-02-10 08:48:59','2026-02-10 08:48:59','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',67,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\"><a href=\\\"https://www.thirtysevenfive.com\\\">La technologie 37.5</a> au service de votre sommeil : respirabilité\", \"identifier\": \"Pack DreamPlus\", \"product_index\": 57}');
INSERT INTO `chunks` VALUES ('947d60ad-45f9-4d2c-81ca-a28d993e46b0',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','pl427118',NULL,'2026-03-20 04:57:42','2026-03-20 04:57:42','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',153,'{\"type\": \"statistical_alias\", \"field\": \"product_reference\", \"value\": \"PL427118\", \"identifier\": \"trophée  en verre forme de flamme\", \"product_index\": 143}'),('9480ca51-2d99-49d7-a40a-1a2d420ddd1e',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: 3x15 cm font li li font color 000000 poids carton 9',NULL,'2026-03-20 06:19:56','2026-03-20 06:19:56','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',426,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"3×15 cm</font></li><li><font color=\\\"#000000\\\">Poids carton: 9\", \"identifier\": \"stylus en aluminium soft-touch\", \"product_index\": 416}'),('9483fe2a-9ba9-498c-b009-240fbbf58bda',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: p strong parure de stylos promotionnelle en metal corps noir et attributs chromes strong p ul li 1 stylo a bille systeme twist et 1 stylo roller en metal avec capuchon li li encre bleu li li dimension de la boite 18x7',NULL,'2026-03-20 06:03:41','2026-03-20 06:03:41','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',376,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"<p><strong>Parure de stylos promotionnelle en métal corps noir et attributs chromés</strong></p><ul><li>1 stylo à bille système twist et 1 stylo roller en métal avec capuchon</li><li>Encre: Bleu</li><li>Dimension de la boite: 18×7\", \"identifier\": \"parure de stylos promotionnelle\", \"product_index\": 366}'),('94862752-d259-429d-8e05-5913b166d13d',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: b b style font family inherit',NULL,'2026-03-20 06:09:59','2026-03-20 06:09:59','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',395,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"</b><b style=\\\"font-family: inherit\", \"identifier\": \"multi câble ecologique avec mousqueton\", \"product_index\": 385}'),('948da646-1fcb-409b-86a9-cb9b33c71b2a','2661a8de-8cb4-4964-af1c-1e80f2ed905a',NULL,'rsonnes souffrant de maux de dos sont plus à l’aise sur un matelas plus fermes, cela dépend vraiment de chaque individu. Une étude publiée dans la revue médicale The Lancet en 2003 a montré qu’un matelas modérément ferme peut fournir les meilleurs résultats pour les personnes souffrant de maux de dos non spécifiques, mais si vous trouvez qu’un matelas plus doux vous aide à dormir confortablement, alors c’est le bon matelas pour vous. Il est également conseillé de remplacer le vieux matelas sur lequel vous dormez depuis des années. En effet, celui-ci a tendance à s’affaisser aux endroits où vous dormez.',NULL,'2026-02-16 18:37:42','2026-02-16 18:37:42','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('9493b5d8-156b-45c2-84cc-077f63adf0b9','ece637d4-4fb6-414a-bd13-c0bb9e4f4611',NULL,'Page: Nos conseils pour bien choisir un matelas de qualité\nURL: https://inayya.re/nos-conseils-pour-bien-choisir-un-matelas-de-qualite\n\n<strong>Le choix d\'un matelas </strong>est une décision importante qui peut avoir un impact sur votre sommeil et votre bien-être général.<strong> Avec la variété de matelas disponibles sur le marché,</strong> il peut être difficile de trouver<strong> le juste équilibre entre qualité et prix abordable</strong>. Dans ce blog, nous allons vous donner <strong>des conseils importants</strong> pour <strong>choisir un matelas confortable et de qualité.</strong>\r\n<ol>\r\n 	<li><strong>Comprendre vos besoins :</strong></li>\r\n</ol>\r\nComprendre vos besoins commence par <strong>une introspection approfondie pour identifier vos préférences individuelles.',NULL,'2026-02-16 18:28:24','2026-02-16 18:28:24','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('949573f0-2651-4283-883b-a56d21d4eba5',NULL,'bc12a7c2-c770-4612-b416-7babc