6-03-20 06:27:11','2026-03-20 06:27:11','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',452,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"Cable Intput: 12V-1.5A /&nbsp\", \"identifier\": \"power bank personnalisable 10000 mah\", \"product_index\": 442}'),('987f3953-904d-4247-a81a-10463042296a',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','false',NULL,'2026-02-10 08:37:27','2026-02-10 08:37:27','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',11,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"false\", \"identifier\": \"Matelas Inayya First\", \"product_index\": 1}'),('9885ee59-702e-4473-8cf4-a80ef11de35a',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','porte cartes de visite li li dimensions 10',NULL,'2026-03-20 05:41:07','2026-03-20 05:41:07','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',296,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"PORTE CARTES DE VISITE</li><li>DIMENSIONS : 10\", \"identifier\": \"cube papier transparent\", \"product_index\": 286}'),('98860dba-6741-4b1c-b32e-d81be5e5f259','35c2d98f-3676-4c1f-b338-4fce37552bf7',NULL,'ombreuses études démontrent qu’une séance de yoga peut améliorer le sommeil pour une variété de populations différentes. Ces études se concentrent généralement sur la qualité du sommeil plutôt que sur la quantité, car une augmentation de la quantité de sommeil n\'est pas nécessairement liée plutôt à un sommeil de qualité et au bien-être général. </span>\r\n\r\n<span style=\"font-weight: 400;\">Pour passer une nuit de sommeil réparateur de bonne qualité, vous devez tout d’abord savoir les bienfaits du yoga:</span>\r\n\r\n<b>Amélioration de la respiration :</b><span style=\"font-weight: 400;\"> La respiration est une partie essentielle du yoga, donc une pratique régulière du yoga peut vous aider à devenir plus conscient de votre respiration et de la façon dont elle affecte votre esprit et votre corps. </span>\r\n\r\n<span style=\"font-weight: 400;\">La respiration profonde, en particulier, peut aider à détendre votre corps et à améliorer votre sommeil.</span>\r\n\r\n<b>Une pleine conscience :</b><span style=\"font-weight: 400;\"> Le yoga peut également être utile car il s\'agit d\'une approche consciente de l\'activité physique.',NULL,'2026-02-16 18:35:28','2026-02-16 18:35:28','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('988c8f56-d8a3-4c4e-b5e8-ebe6beeeb596',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','product name: matelas hotel 5',NULL,'2026-03-20 12:44:22','2026-03-20 12:44:22','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',172,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"Matelas Hotel 5\", \"identifier\": \"Matelas Hotel 5\", \"product_index\": 162}'),('988cbb42-aa45-49ea-b14b-cf7154571cef',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','le strong pack dream cooling strong convient parfaitement aux personnes recherchant un ensemble literie a la fois ferme et confortable l epaisseur et la qualit e de la mousse a m emoire de forme visco s electionn ee pour ce matelas lui conf erent un accueil doux et ergonomique sans etre trop moelleux la couche de mousse haute densit e du noyau assure',NULL,'2026-02-10 09:53:01','2026-02-10 09:53:01','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',245,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\">Le <strong>Pack Dream Cooling</strong> convient parfaitement aux personnes recherchant un ensemble literie à la fois ferme et confortable. L’épaisseur et la qualité de la mousse à mémoire de forme VISCO sélectionnée pour ce matelas lui confèrent un accueil doux et ergonomique sans être trop moelleux. La couche de mousse Haute Densité du noyau assure\", \"identifier\": \"Le Pack Dream Cooling\", \"product_index\": 235}'),('988d758d-fdfe-48c1-8d3e-072569ea8ff5',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','https planetdesign ma article stylo en bambou pl112164 na',NULL,'2026-03-20 0