d85af','import',50,NULL),('bfebf3b4-6d91-499f-88a5-46b4e83c7392',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','2025 01 28 17 28 27',NULL,'2026-03-20 05:27:36','2026-03-20 05:27:36','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',253,'{\"type\": \"statistical_alias\", \"field\": \"created_at\", \"value\": \"2025-01-28 17:28:27\", \"identifier\": \"stylus en métal de luxe\", \"product_index\": 243}'),('bfec354d-94e0-4912-b80c-1366adb25c72','021fa1dc-4d76-48c0-b436-9e4053f129d3',NULL,'Page: Cuisine Habitat - Conseils de Décoration pour les Petites... Section: 5. Opter pour des électroménagers compacts :\nURL: https://cuisinehabitat.re/conseil-deco-petite-cuisine-equipee/\n\nDans une petite cuisine, chaque électroménager compte. Choisissez des appareils électroménagers compacts et multifonctionnels, comme un four combiné micro-ondes, un lave-vaisselle encastrable ou un réfrigérateur à tiroirs. Pour économiser de l’espace tout en conservant toutes les fonctionnalités nécessaires.',NULL,'2026-02-09 15:26:53','2026-02-09 15:26:53','d75f16dd-64a5-47eb-a13b-290285cd85af','sitemap',60,NULL),('bfee5fc3-aafa-4cef-a722-9d35887f624b',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','le sommier mod ele italie',NULL,'2026-02-10 09:02:33','2026-02-10 09:02:33','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',109,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"Le Sommier (Modèle Italie)\", \"identifier\": \"Le Sommier (Modèle Italie)\", \"product_index\": 99}'),('bfeefdd5-ad38-4bf2-8a5e-6360588d8b02',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','center',NULL,'2026-02-10 08:49:39','2026-02-10 08:49:39','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',67,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"testé par des laboratoires européens indépendants et par le US Olympic Training Center.</p>\\r\\\\n\\r\\\\n<h3 style=\\\"font-size: 20px\", \"identifier\": \"Pack DreamPlus\", \"product_index\": 57}'),('bfef7eb8-1a66-4884-bbb1