ement visuel indésirable.',NULL,'2026-02-09 15:38:35','2026-02-09 15:38:35','d75f16dd-64a5-47eb-a13b-290285cd85af','sitemap',60,NULL),('ca1166da-dcac-4352-955c-2a1280165155',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','parure de stylos publicitaire luxury',NULL,'2026-03-20 05:25:39','2026-03-20 05:25:39','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',247,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"parure de stylos publicitaire luxury\", \"identifier\": \"parure de stylos publicitaire luxury\", \"product_index\": 237}'),('ca20a2e0-4790-45d0-8a52-e86781808a81',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','product name: matelas inayya luxury',NULL,'2026-02-10 10:06:47','2026-02-10 10:06:47','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',310,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"Matelas  Inayya Luxury\", \"identifier\": \"Matelas  Inayya Luxury\", \"product_index\": 300}'),('ca234859-71c5-4c81-871d-215a9b1994d4',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','image url: https planetdesign ma assets resources articles 866e3211 c27c 4c9d b6e7 00a472ddea12 png',NULL,'2026-03-20 04:39:41','2026-03-20 04:39:41','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',83,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/866e3211-c27c-4c9d-b6e7-00a472ddea12.png\", \"identifier\": \"mini note book de poche post-it ecologique\", \"product_index\": 73}'),('ca23b7fe-e6ea-4e13-a58c-6985276acb62',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','coffret vip publicitaire 5 pieces',NULL,'2026-03-20 05:55:09','2026-03-20 05:55:09','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',346,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"coffret vip publicitaire 5 pièces\", \"identifier\": \"coffret vip publicitaire 5 pièces\", \"product_index\": 336}'),('ca27fb3b-c3b4-4006-9652-efc916be76c6',NULL,'5815ed6d-02dd-4df1-9