\", \"product_index\": 107}'),('cabd83a0-45a6-4efb-9c59-97542c051f1e',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','499a',NULL,'2026-03-20 12:46:48','2026-03-20 12:46:48','3bb879f9-b0fd-4b5d-b256-dd7052e876db','woocommerce',183,'{\"type\": \"statistical_alias\", \"field\": \"gallery_urls\", \"value\": \"https://drmaxisliterie.re/assets/resources/products/6657d807-ac91-499a-b281-a8875016f234.jpg\", \"identifier\": \"LIT BUBBLE\", \"product_index\": 173}'),('cac15253-4be0-423a-b41c-13353be24b40',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','product name: mat elas inayya cooling 140x190',NULL,'2026-02-10 09:50:28','2026-02-10 09:50:28','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',239,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"Matélas inayya Cooling 140x190\", \"identifier\": \"Matélas inayya Cooling 140x190\", \"product_index\": 229}'),('cac34dd2-db02-4c2d-9123-8c629328dfad',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: 1000 pcs li li dimension carton nbsp',NULL,'2026-03-20 04:28:14','2026-03-20 04:28:14','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',46,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"1000 pcs</li><li>Dimension carton:&nbsp\", \"identifier\": \"stylo en plastique personnalisable\", \"product_index\": 36}'),('cac42e95-a13c-434d-94de-c49981bc5df1',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','description: font size 17px',NULL,'2026-02-10 09:27:42','2026-02-10 09:27:42','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',169,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"font-size: 17px\", \"identifier\": \"Matelas Inayya Eco - 160x200\", \"product_index\": 159}'),('cac5429e-f977-462b-a963-dfd4ac771beb','5603e48c-ef3f-4eaf-ac34-d830fe1a0632',NULL,'Page: Les différents matelas suivant votre corpulence\nURL: https://inayya.re/les-differents-matelas-suivant-votre-corpulence\n\nAvec les nombreux matelas sur le marché, en trouver un qui vous convienne est difficile. Pour faire le bon choix, vous devez prendre en compte votre corpulence. Étant différent, chaque individu possède leur propre besoin suivant leur morphologie. Le matelas doit dépendre de votre taille et de votre poids, mais également de la caractéristique du matelas. Pourquoi choisir un matelas adapté à sa morphologie ? <strong>Le corps doit être correctement soutenu pendant le sommeil pour assurer un repos maximal.</strong> Ainsi, votre colonne vertébrale doit être alignée de façon parfaite. Si le matelas est trop souple, il ne vous apportera pas assez de soutien.',NULL,'2026-02-16 18:37:55','2026-02-16 18:37:55','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('cac9d19c-a800-4c13-8656-5a2d267b9799','8b81759d-5ba5-4054-ab2a-7bf6fe3d9678',NULL,'erver l’apparence de <strong><em>votre dressing sur mesure</em></strong>, établissez une routine de nettoyage régulière. Utilisez un chiffon doux et sec pour dépoussiérer les surfaces, et évitez les produits chimiques agressifs qui pourraient endommager les matériaux. Pour les surfaces en bois, un nettoyant spécifique pour bois peut être utilisé de temps en temps.<br/>\r\nPour des conseils sur le nettoyage des surfaces en bois, consultez cet <a style=\"color: #2ea3f2;\" href=\"https://www.exemple.com/entretien-du-bois\" target=\"_new\" rel=\"noreferrer noopener\">article sur l\'entretien du bois</a>.',NULL,'2026-02-16 16:11:29','2026-02-16 16:11:29','d75f16dd-64a5-47eb-a13b-290285cd85af','import',50,NULL),('cacf8ffe-dba5-407d-bf8c-b129319c466d',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','product url: https planetdesign ma article pot a crayon publicitaire avec horloge digitale pl151008',NULL,'2026-03-20 06:28:30','2026-03-20 06:28:30','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',455,'{\"type\": \"statistical_alias\", \"field\": \"product_url\", \"value\": \"https://planetdesign.ma/article/pot-a-crayon-publicitaire-avec-horloge-digitale/PL151008\", \"identifier\": \"pot à crayon publicitaire  avec horloge digitale\", \"product_index\": 445}'),('cad1acc5-e7d8-4a7b-a2f1-8df38c154cb6',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','5x52 cm font li li style margin 0px',NULL,'2026-03-20 04:34:04','2026-03-20 04:34:04','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',63,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"5x52 cm</font></li><li style=\\\"margin: 0px\", \"identifier\": \"bouteille en verre  à bouchon en bamboo  avec pochette 600 ml\", \"product_index\": 53}'),('cad72011-4e56-4847-8af7-e51f1b77c730',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','pl211098',NULL,'2026-03-20 04:47:39','2026-03-20 04:47:39','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',115,'{\"type\": \"statistical_alias\", \"field\": \"product_reference\", \"value\": \"PL211098\", \"identifier\": \"power-bank 5000 mah\", \"product_index\": 105}'),('cad87f26-e52b-45c0-9fdf-249714cb32fa',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','description: strong le sommier strong h3 n p style font size 17px',NULL,'2026-02-10 08:49:40','2026-02-10 08:49:40','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',67,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"\\\"><strong>LE SOMMIER</strong></h3>\\r\\\\n<p style=\\\"font-size: 17px\", \"identifier\": \"Pack DreamPlus\", \"product_index\": 57}'),('cad930bc-85fb-4c17-b0f0-7de5713f6604',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','created at: 2025 01 30 13 11 11',NULL,'2026-03-20 04:22:29','2026-03-20 04:22:29','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',30,'{\"type\": \"statistical_alias\", \"field\": \"created_at\", \"value\": \"2025-01-30 13:11:11\", \"identifier\": \"porte-clés publicitaire design camion\", \"product_index\": 20}'),('cae0d5ca-7b22-41c9-bf88-c70c90091fe2',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','description: li li emballage boite en carton nbsp',NULL,'2026-03-20 05:12:10','2026-03-20 05:12:10','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',204,'{\"type\": \"statistical_alias\", \"field\": \"description\", \"value\": \"</li><li>Emballage: Boite en carton&nbsp\", \"identifier\": \"conférencier a4 en simili-cuir et tissu\", \"product_index\": 194}'),('cae45006-ae10-4e97-be20-e58c409511dc',NULL,'296a8f2c-2cc9-45af-9d6e-100b87ff6e43','Product name: Matelas Maxis Cool. Product reference: xm5. Product category: Matelas. Description: Le Matelas MAXIS COOL offre un confort optimal avec son tissu rafraîchissant en soie glacée et sa mousse à mémoire hydrophile qui s’adapte aux contours du corps. L’éponge haute densité et la mousse respirante assurent une ventilation idéale pour un sommeil frais et agréable. Les ressorts ensachés indépendants de 22 cm apportent un soutien zoné et une parfaite indépendance de couchage. Ce matelas garantit une gestion de l\'humidité efficace grâce à son coton thermolié. Il offre ainsi un confort durable pour un sommeil réparateur.    GARANTIE 10 ANS. Le Matelas MAXIS COOL est parfait pour ceux qui cherchent à combiner confort, soutien et régulation thermique. Il convient particulièrement aux personnes qui ont tendance à avoir chaud la nuit grâce à son tissu rafraîchissant en soie glacée et sa mousse respirante. Ce matelas est également idéal pour les couples ou ceux qui partagent leur lit, grâce à ses ressorts ensachés indépendants qui minimisent les perturbations dues aux mouvements nocturnes. Enfin, avec sa mousse à mémoire de forme et son soutien zoné, il est recommandé pour ceux souffrant de douleurs corporelles ou de tensions musculaires, en apportant un soutien adapté à chaque zone du corps pour un confort optimal.. Short description: Le matelas MAXIS COOL de Dr Maxis Literie La Réunion combine soie glacée rafraîchissante et mousse à mémoire hydrophile avec ressorts ensachés 22cm. Soutien zoné optimal pour couples et sommeil réparateur. Garantie 10 ans.. Features: 1.09 757 L200 * l160 * H34 (cm)|1.22 868 L200 * l180 * H34 (cm). Keywords: matelas La Réunion , Dr Maxis Literie , soie glac