, \"product_index\": 478}'),('e7547428-f6a3-4f93-894b-718124c8bc14','281904fa-02c5-490b-8831-78ab5ae262a1',NULL,'t essentiels pour <strong>un sommeil réparateur</strong>.</p>\r\n\r\n<h2 style=\"color: #000000; font-size: 20px;\"><strong>3. Limiter l\'Exposition aux Écrans Avant de Dormir</strong></h2>\r\n<p style=\"color: #000000; font-size: 17px;\">Les écrans d’ordinateurs, de télévisions, de tablettes et de téléphones émettent une lumière bleue qui peut perturber la production de mélatonine, l’hormone du sommeil. Essayez de limiter l’utilisation de ces appareils au moins une heure avant d’aller au lit. Optez plutôt pour des activités relaxantes comme la lecture d’un livre (papier), la méditation ou l’écoute de musique douce.</p>\r\n\r\n<h2 style=\"color: #000000; font-size: 20px;\"><strong>4.',NULL,'2026-02-16 18:23:43','2026-02-16 18:23:43','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('e754c6ec-df86-4bdc-b9d9-e24a2108db12',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','546e4bd69ff2',NULL,'2026-03-20 06:26:27','2026-03-20 06:26:27','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',450,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/1039fde6-6f71-45de-9445-546e4bd69ff2.png\", \"identifier\": \"trophée en verre et bois forme flamme\", \"product_index\": 440}'),('e755300f-a0d2-422a-ae8b-de9642f7ef48',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','https planetdesign ma assets resources articles 0da35d25 254e 477b b46c 4e187922eba0 png',NULL,'2026-03-20 06:38:52','2026-03-20 06:38:52','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',485,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/0da35d25-254e-477b-b46c-4e187922eba0.png\", \"identifier\": \"boucles d’oreilles mini b swarovski\", \"product_index\": 475}'),('e7560a5e-6244-43fe-9d99-68dfd89719eb',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','devenant',NU