}'),('f71133eb-1855-4b0e-a68c-71c4af2531f3','e979066f-ed8f-47aa-a2f5-74291b4a45f7',NULL,'ressorts ensachés sont plus frais que<strong> les matelas en mousse à mémoire</strong> grâce à la circulation de l\'air. <strong>-Soutien de Bord</strong> : <strong>Les ressorts ensachés</strong> offrent un soutien optimal sur les bords du matelas, adapté pour s\'asseoir ou dormir près du bord. <strong>-Réactivité </strong>: <strong>Les matelas à ressorts ensachés </strong>réagissent plus rapidement, ce qui peut être préférable pour ceux qui bougent souvent pendant leur sommeil. <strong>Inconvénients :</strong>\r\n\r\n<strong>Les matelas à ressorts ensachés</strong> peuvent vous déranger si votre partenaire bouge beaucoup, <strong>car ils transfèrent les mouvements.</strong>\r\n\r\n<strong>Les matelas à ressorts ensachés</strong> ont tendance à transmettre les mouvements d\'une personne à l\'autre.',NULL,'2026-02-16 18:30:03','2026-02-16 18:30:03','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','import',50,NULL),('f71209ec-b792-4781-89a3-109497b138d9',NULL,'5815ed6d-02dd-4df1-9f2d-b132dd4e6c4a','le pack inayya slumber matelas inayya slumber sommier',NULL,'2026-02-10 10:13:53','2026-02-10 10:13:53','26f613e9-bd9c-4ee3-b194-5a84b6c1a420','woocommerce',356,'{\"type\": \"statistical_alias\", \"field\": \"product_name\", \"value\": \"Le Pack Inayya Slumber - Matelas Inayya Slumber+ Sommier\", \"identifier\": \"Le Pack Inayya Slumber - Matelas Inayya Slumber+ Sommier, 140x190cm\", \"product_index\": 346}'),('f712a101-8fcc-4724-8053-f5b042ffeaeb',NULL,'bc12a7c2-c770-4612-b416-7babc4bed4df','4f88',NULL,'2026-03-20 06:14:10','2026-03-20 06:14:10','1e0d17be-c7ef-4713-9082-3e6b2845afc6','woocommerce',407,'{\"type\": \"statistical_alias\", \"field\": \"image_url\", \"value\": \"https://planetdesign.ma/assets/resources/articles/dc5fa39e-e3a5-4f88-ae6d-93937f432a5e.png\", \"identifier\": \"usb 32 gb personnalisable en bois forme oval\", \"product_index\": 397}'),('f7130bc0-3154-443a-a965-8ce9ad91e195'