INSERT INTO `messages` VALUES ('0f8fbaa6-db7e-4fa9-937e-e0b3bbae60d4','4775a66b-ebb6-442a-9a3e-85f60c31d746',NULL,'Bonjour je suis intérer par une cuisine luxy','user','2026-03-16 18:38:00','2026-03-16 18:38:00',NULL),('0fee81bd-0c60-43ef-b797-9ff0e6469b2d','4fb64c33-c166-43db-9ed7-2c1c97e92d7f',NULL,'Bonjour je veux une cuisine moderne','user','2026-03-17 13:48:24','2026-03-17 13:48:24',NULL),('38a4cc9f-3f02-4dab-aba4-188c8919d4e2','29ad61e0-0061-4551-bda5-b0eb4ab61bf7',NULL,'Bonjour je suis intérer par une cuisine luxy','user','2026-03-16 18:59:07','2026-03-16 18:59:07',NULL),('44a56488-bc90-41a6-88a0-c213cf665936','967a8269-99b7-474c-824c-5e9f6c0bb3cb',NULL,'Bonjour je suis intérer par une cuisine luxy','user','2026-03-16 18:45:27','2026-03-16 18:45:27',NULL),('6544b241-7c5e-4de8-a6ea-cffcea5f09ab','4fb64c33-c166-43db-9ed7-2c1c97e92d7f',NULL,'Nous avons une offre qui pourrait vous intéresser pour une cuisine moderne. Nous proposons la surface \"Luxe by Alvic\", qui convient parfaitement à ce style. Elle offre une beauté extraordinaire avec sa réflexion et sa finition de haute qualité, résistante aux rayures et aux taches alimentaires. Elle est également facile à entretenir et à nettoyer, tout en étant respectueuse de l\'environnement. Elle est disponible en plusieurs couleurs.','bot','2026-03-17 13:48:47','2026-03-17 13:48:47',NULL),('8ae8b4db-ce56-458d-ac26-9fd4ba5f815d','29ad61e0-0061-4551-bda5-b0eb4ab61bf7',NULL,'Nous proposons la surface laquée \"Luxe by Alvic\", qui offre une beauté extraordinaire avec sa reflexion et sa finition haute qualité. C\'est une option idéale pour les cuisines modernes et luxueuses qui recherchent une surface facile à entretenir et à nettoyer, respectueuse de l\'environnement et fabriquée à partir de matières premières certifiées provenant de forêts durables.','bot','2026-03-16 18:59:21','2026-03-16 18:59:21',NULL),('b824a189-9da7-44ff-bf65-b8f31c44ec50','eee1df9c-7b57-4182-9baa-3eab6dbe465a',NULL,'Nous avons une gamme de cuisines équipées appelée \"Luxe by Alvic\" qui convient parfaitement à votre demande. Cette cuisine offre une surface laquée à haute brillance avec effet miroir, idéale pour les cuisines modernes et luxueuses. Elle dispose de caractéristiques telles que la haute brillance, la technologie luxe pour une beauté extraordinaire, et une finition haute qualité. Nous disposons de différentes couleurs disponibles, notamment l\'Anthracite, le Basalto, le Blanco, le Cashmere et le Gris Nube. Cette cuisine est disponible en stock. Si vous souhaitez en savoir plus ou obtenir des informations sur les disponibilités, nous serions ravis de vous aider.','bot','2026-03-16 18:52:04','2026-03-16 18:52:04',NULL),('bca66d88-cd29-43b1-9a92-918ecc82c737','eee1df9c-7b57-4182-9baa-3eab6dbe465a',NULL,'Bonjour je suis intérer par une cuisine luxy','user','2026-03-16 18:51:43','2026-03-16 18:51:43',NULL),('c9afd171-fe22-4759-95d9-6b6802b6584d','967a8269-99b7-474c-824c-5e9f6c0bb3cb',NULL,'Nous proposons la gamme \"Luxe by Alvic\" qui correspond à votre demande de cuisine luxueuse. Cette série de surfaces de cuisine haute brillance offre une beauté extraordinaire avec sa reflexion et sa finition haute qualité. Les surfaces sont faciles à entretenir, respectueuses de l\'environnement et fabriquées à partir de matériaux certifiés provenant de forêts durables. Nous avons cette gamme disponible en stock.','bot','2026-03-16 18:45:47','2026-03-16 18:45:47',NULL),('cdd81c4e-3824-40ea-839f-73ebb2fce04b','4775a66b-ebb6-442a-9a3e-85f60c31d746',NULL,'Nous proposons la gamme LUXE BY ALVIC, qui correspond parfaitement à vos attentes pour une cuisine luxueuse. Cette gamme offre une surface laquée haute brillance avec effet miroir, idéale pour les cuisines modernes et luxueuses.','bot','2026-03-16 18:38:19','2026-03-16 18:38:19',NULL);
